    function cronNext(c, from, count) {
        var d = new Date(from); d.setSeconds(0, 0); d.setMinutes(d.getMinutes() + 1);
        var limit = from + 5 * 366 * 86400000, res = [];
        var dayOk = function (x) {
            var a = !!c.dom.set[x.getDate()], b = !!c.dow.set[x.getDay()];
            if (c.dom.star && c.dow.star) return true;
            if (c.dom.star) return b;
            if (c.dow.star) return a;
            return a || b;
        };
        while (res.length < count && d.getTime() < limit) {
            if (!c.mon.set[d.getMonth() + 1]) { d.setMonth(d.getMonth() + 1, 1); d.setHours(0, 0, 0, 0); continue; }
            if (!dayOk(d)) { d.setDate(d.getDate() + 1); d.setHours(0, 0, 0, 0); continue; }
            if (!c.h.set[d.getHours()]) { d.setHours(d.getHours() + 1, 0, 0, 0); continue; }
            if (!c.mi.set[d.getMinutes()]) { d.setMinutes(d.getMinutes() + 1, 0, 0); continue; }
