                      else { var mk = ip2n(m[3]); if (mk !== null) { var b = (~mk >>> 0) + 1; pre = (b & (b - 1)) === 0 ? 32 - Math.round(Math.log(b) / Math.LN2) : -1; } }
                  }
                  if (!m || ip === null || pre === undefined || pre < 0 || pre > 32) { ids.forEach(function (i) { set(i, '-'); }); set('cidr-hosts', '형식: 10.0.0.0/16 또는 10.0.0.0 255.255.0.0'); return; }
                  var mask = pre === 0 ? 0 : (0xFFFFFFFF << (32 - pre)) >>> 0, net = (ip & mask) >>> 0, bc = (net | (~mask >>> 0)) >>> 0, total = Math.pow(2, 32 - pre);
                  var hosts = pre === 32 ? 1 : pre === 31 ? 2 : total - 2;
                  set('cidr-net', n2ip(net) + '/' + pre); set('cidr-bc', n2ip(bc)); set('cidr-mask', n2ip(mask)); set('cidr-wc', n2ip(~mask >>> 0));
                  set('cidr-first', n2ip(pre >= 31 ? net : net + 1)); set('cidr-last', n2ip(pre >= 31 ? bc : bc - 1));
                  set('cidr-hosts', hosts.toLocaleString()); set('cidr-total', total.toLocaleString());
              });
          } },
        { id: 'chmod', title: '파일 권한 변환', desc: '체크박스 ↔ 640 ↔ rw-r-----', lead: '체크박스, 숫자, 기호 중 하나를 바꾸면 나머지가 따라 바뀝니다.',
          html: function () {
              var who = [['u', 'owner'], ['g', 'group'], ['o', 'other']], bits = [['r', 4], ['w', 2], ['x', 1]];
              return '<table class="tbx-perm"><tbody>' + who.map(function (w) {
                  return '<tr><th scope="row">' + w[1] + '</th>' + bits.map(function (b) { return '<td><label><input type="checkbox" id="tb-chmod-' + w[0] + b[0] + '" data-v="' + b[1] + '"> ' + b[0] + '</label></td>'; }).join('') + '</tr>';
              }).join('') + '</tbody></table>' +
              '<div class="tbx-form">' + field('chmod-n', 'numeric', 'inputmode="numeric" maxlength="4" value="644"', 'half') + field('chmod-s', 'symbolic', 'maxlength="10"', 'half') + '</div>' +
              out('chmod-cmd', 'command', { hl: 1, copy: 1 }) + out('chmod-ls', 'ls -l'); },
          run: function () {
              var W = ['u', 'g', 'o'], B = ['r', 'w', 'x'];
              function apply(digits, from) {
                  W.forEach(function (w, i) { var d = +digits[i]; B.forEach(function (b, j) { $t('chmod-' + w + b).checked = !!(d & (4 >> j)); }); });
                  var sym = digits.split('').map(function (d) { d = +d; return (d & 4 ? 'r' : '-') + (d & 2 ? 'w' : '-') + (d & 1 ? 'x' : '-'); }).join('');
                  if (from !== 'n') $t('chmod-n').value = digits;
                  if (from !== 's') $t('chmod-s').value = sym;
                  set('chmod-cmd', 'chmod ' + digits + ' FILE'); set('chmod-ls', '-' + sym);
              }
              function fromBoxes() { apply(W.map(function (w) { return B.reduce(function (s, b, j) { return s + ($t('chmod-' + w + b).checked ? 4 >> j : 0); }, 0); }).join(''), 'c'); }
              W.forEach(function (w) { B.forEach(function (b) { $t('chmod-' + w + b).addEventListener('change', fromBoxes); }); });
              $t('chmod-n').addEventListener('input', function () { var v = this.value.trim(); if (/^0?[0-7]{3}$/.test(v)) apply(v.slice(-3), 'n'); });
              $t('chmod-s').addEventListener('input', function () {
                  var v = this.value.trim(); if (v.length === 10) v = v.slice(1);
                  if (!/^([r-][w-][xsStT-]){3}$/.test(v)) return;
                  apply([0, 3, 6].map(function (i) { return (v[i] === 'r' ? 4 : 0) + (v[i + 1] === 'w' ? 2 : 0) + (/[xst]/.test(v[i + 2]) ? 1 : 0); }).join(''), 's');
              });
              apply($t('chmod-n').value, '');
          } },
        { id: 'cron', title: 'cron 표현식 풀이', desc: '5필드 cron → 한국어 + 다음 실행 5회', lead: 'crontab 한 줄을 풀어 읽고, 다음 실행 시각 5개를 확인합니다.',
          html: function () { return '<div class="tbx-form">' + field('cron-v', '분 시 일 월 요일', 'value="0 2 * * 1-5"', 'wide') + '</div>' +
                out('cron-d', '풀이', { hl: 1 }) + '<div class="tbx-out top"><span class="k">다음 실행</span><ol class="v tbx-runs" id="tb-cron-n"></ol><span></span></div>' +
                '<p class="tbx-note">브라우저 시간대 기준입니다. <code>*/5</code> <code>1-5</code> <code>1,15</code> <code>MON-FRI</code> <code>@daily</code> 를 지원합니다.</p>'; },
          run: function () {
              bind(['cron-v'], function () {
                  var c;
                  try { c = cronParse($t('cron-v').value); } catch (e) { level(set('cron-d', '[ERROR] 5개 필드(분 시 일 월 요일)를 확인하세요'), 'lvl-crit'); $t('cron-n').innerHTML = ''; return; }
                  level(set('cron-d', cronDescribe(c)), '');
                  var runs = cronNext(c, Date.now(), 5);
                  $t('cron-n').innerHTML = runs.length ? runs.map(function (d) { return '<li>' + localStr(d).replace(' ', ' (' + DOW[d.getDay()] + ') ') + '</li>'; }).join('') : '<li>5년 안에 실행되지 않습니다</li>';
              });
          } },
        { id: 'encode', title: 'URL · Base64 인코딩', desc: '인코딩/디코딩, UTF-8', lead: 'URL 파라미터, Basic 인증 헤더, 설정 파일의 Base64 값을 만들거나 풉니다. UTF-8 기준.',
          html: function () { return '<div class="tbx-form">' + select('enc-m', 'mode', [['url-enc', 'URL encode'], ['url-dec', 'URL decode'], ['b64-enc', 'Base64 encode'], ['b64-dec', 'Base64 decode']], 'url-enc', 'half') +
                '<label class="tbx-f wide"><span>input</span><textarea class="tbx-ta" id="tb-enc-v" spellcheck="false">q=SSLHandshakeException 한글</textarea></label></div>' +
                out('enc-o', 'output', { block: 1, copy: 1 }) + out('enc-len', 'length'); },
          run: function () {
              bind(['enc-m', 'enc-v'], function () {
                  var m = $t('enc-m').value, v = $t('enc-v').value, r, el;
                  try {
                      r = m === 'url-enc' ? encodeURIComponent(v) : m === 'url-dec' ? decodeURIComponent(v.replace(/\+/g, ' ')) : m === 'b64-enc' ? b64enc(v) : b64dec(v);
                      el = set('enc-o', r); level(el, ''); set('enc-len', v.length + ' → ' + r.length + ' chars');
                  } catch (e) { level(set('enc-o', '[ERROR] 이 모드로 디코딩할 수 없는 입력입니다'), 'lvl-crit'); set('enc-len', '-'); }
              });
          } },
        { id: 'cert', title: '인증서 만료일 계산', desc: '만료일 → 남은 일수, 30일 이하 경고', lead: '만료일이나 openssl·keytool 출력 한 줄을 붙여넣으면 남은 일수를 계산합니다.',
          html: function () { return '<div class="tbx-form">' + field('cert-v', '만료일 또는 notAfter / Valid until 줄', 'placeholder="notAfter=Nov 13 23:59:59 2027 GMT 또는 2027-11-13"', 'wide') + '</div>' +
                out('cert-days', '남은 일수', { hl: 1 }) + out('cert-at', '만료 시각 (KST)', { copy: 1 }) + out('cert-l', 'level') +
                '<p class="tbx-note">만료일을 뽑는 명령은 <a href="#cmd">./cmd</a> 의 &#8216;만료일 조회&#8217;에 있습니다.</p>'; },
          run: function () {
              bind(['cert-v'], function () {
                  var v = $t('cert-v').value.trim(), t = NaN, m;
                  if ((m = v.match(/^(\d{4})[-.\/](\d{1,2})[-.\/](\d{1,2})$/))) t = Date.UTC(+m[1], +m[2] - 1, +m[3], 23, 59, 59) - 9 * 3600000;
                  else if (v) {
                      var s = v.replace(/^.*?(notAfter=|until:\s*|Not After\s*:\s*)/i, '').replace(/\bKST\b/, 'GMT+0900');
                      t = Date.parse(s);
                  }
                  if (isNaN(t)) { set('cert-days', '-'); set('cert-at', '-'); level(set('cert-l', v ? '[ERROR] 날짜를 읽지 못했습니다' : '-'), v ? 'lvl-crit' : ''); return; }
                  var days = Math.floor((t - Date.now()) / 86400000), lv = days < 0 ? 'crit' : days <= 30 ? 'warn' : 'ok';
                  level(set('cert-days', days < 0 ? Math.abs(days) + ' days ago' : days + ' days'), 'lvl-' + lv);
                  set('cert-at', fmtDate(t, 9));
                  level(set('cert-l', lv === 'crit' ? '[EXPIRED] 이미 만료되었습니다' : lv === 'warn' ? '[WARN] 30일 이하, 교체 일정을 잡으세요' : '[OK] 30일 넘게 남았습니다'), 'lvl-' + lv);
              });
          } },
        { id: 'cmd', title: 'keytool · openssl 명령어', desc: 'PKCS12·체인·만료일·keystore 목록', lead: '인증서 작업에 자주 쓰는 명령어를 호스트와 파일 이름에 맞춰 만듭니다. 비밀번호는 넣지 않습니다.',
          html: function () { return '<div class="tbx-form">' + select('cmd-t', 'task', Object.keys(CMD).map(function (k) { return [k, CMD[k].name]; }), 'p12', 'wide') +
                field('cmd-host', 'host', 'value="www.example.com"', 'half" data-need="host') + field('cmd-port', 'port', 'inputmode="numeric" value="443"', 'narrow" data-need="port') +
                field('cmd-alias', 'alias', 'value="tomcat"', 'half" data-need="alias') + field('cmd-base', 'file name (확장자 없이)', 'value="server"', 'half" data-need="base') + '</div>' +
                out('cmd-o', 'command', { block: 1, copy: 1 }) + '<p class="tbx-note" id="tb-cmd-note"></p>'; },
          run: function () {
              bind(['cmd-t', 'cmd-host', 'cmd-port', 'cmd-alias', 'cmd-base'], function () {
                  var t = CMD[$t('cmd-t').value], v = {};
                  ['host', 'port', 'alias', 'base'].forEach(function (k) { v[k] = $t('cmd-' + k).value.replace(/[^A-Za-z0-9._\-*\/:]/g, '') || k.toUpperCase(); });
                  $$('#tool-cmd [data-need]').forEach(function (f) { f.hidden = t.need.indexOf(f.getAttribute('data-need')) < 0; });
                  set('cmd-o', t.f(v)); set('cmd-note', t.note);
              });
          } }
    ];

    function copyText(text, btn) {
        var done = function () { btn.textContent = 'copied'; btn.classList.add('done'); setTimeout(function () { btn.textContent = 'copy'; btn.classList.remove('done'); }, 1400); };
        if (navigator.clipboard && window.isSecureContext) { navigator.clipboard.writeText(text).then(done, function () { legacy(); }); return; }
        legacy();
        function legacy() {
            var ta = document.createElement('textarea'); ta.value = text; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0';
            document.body.appendChild(ta); ta.select();
            try { document.execCommand('copy'); done(); } catch (e) {}
            document.body.removeChild(ta);
        }
    }

    function init() {
        var app = $('#toolbox-app');
        if (!app) return;
        document.body.classList.add('is-tools');
        // lift the app out of .post-body (keeps post typography off the tools); hide the empty page shell
        var col = $('.post-col'), art = app.closest('article');
        if (col && art) {
            col.insertBefore(app, col.firstChild);
            var body = $('.post-body', art);
            if (!body || !body.textContent.trim()) {
                art.hidden = true;
                var h1 = $('.post-h1', art); if (h1) h1.parentNode.removeChild(h1); // the toolbox title is the page h1
            }
        }
        var layout = $('#layout-post'); if (layout) layout.classList.add('no-toc');
        app.className = 'tbx';
        app.innerHTML =
            '<div class="tbx-head"><h1 class="tbx-title"><b>$</b> ls ./toolbox</h1>' +
            '<p class="tbx-sub">현장에서 자주 꺼내 쓰는 계산과 명령어 ' + TOOLS.length + '개. 입력값은 이 브라우저 밖으로 나가지 않습니다.</p>' +
            '<span class="tbx-keys"><span><kbd>&#8593;</kbd><kbd>&#8595;</kbd> 선택</span><span><kbd>1</kbd>–<kbd>12</kbd> 바로 열기</span></span></div>' +
            '<div class="tbx-grid"><ol class="tbx-list" aria-label="도구 목록">' + TOOLS.map(function (t, i) {
                return '<li><a class="tbx-item" href="#' + t.id + '" data-id="' + t.id + '"><span class="n">' + p2(i + 1) + '</span><span class="nm">' + t.id + '</span><span class="ds">' + t.desc + '</span></a></li>';
            }).join('') + '</ol><div class="tbx-panels">' + TOOLS.map(function (t) {
                return '<section class="tbx-panel" id="tool-' + t.id + '" aria-labelledby="tool-h-' + t.id + '" hidden>' +
                    '<button type="button" class="tbx-back">&#8249; ls ./toolbox</button>' +
                    '<div class="tbx-cmd"><b>$</b> ./' + t.id + '</div><h2 class="tbx-h" id="tool-h-' + t.id + '">' + t.title + '</h2><p class="tbx-desc">' + t.lead + '</p>' + t.html() + '</section>';
            }).join('') + '</div></div>';
        TOOLS.forEach(function (t) { t.run(); });

        var cur = -1, fromClick = false;
        function pick(i, opts) {
            opts = opts || {};
            if (i < 0 || i >= TOOLS.length) return;
            cur = i;
            $$('.tbx-item', app).forEach(function (a, k) { a.classList.toggle('on', k === i); if (k === i) a.setAttribute('aria-current', 'true'); else a.removeAttribute('aria-current'); });
            $$('.tbx-panel', app).forEach(function (p, k) { p.hidden = k !== i; });
            if (opts.open) app.classList.add('open', 'picked');
            if (opts.hash) history.replaceState(null, '', '#' + TOOLS[i].id);
            if (opts.focus) $$('.tbx-item', app)[i].focus();
            if (opts.open && window.matchMedia('(max-width: 900px)').matches) window.scrollTo(0, 0);
        }
        function fromHash() {
            var id = location.hash.slice(1), i = TOOLS.map(function (t) { return t.id; }).indexOf(id);
            if (i >= 0) pick(i, { open: true });
            else { app.classList.remove('open'); pick(cur < 0 ? 0 : cur); }
        }
        window.addEventListener('hashchange', fromHash);
        fromHash();

        app.addEventListener('click', function (e) {
            var item = e.target.closest('.tbx-item');
            if (item) { fromClick = true; if (location.hash === '#' + item.getAttribute('data-id')) { e.preventDefault(); fromHash(); } return; }
            if (e.target.closest('.tbx-back')) {
                if (fromClick) history.back();
                else { history.replaceState(null, '', location.pathname + location.search); fromHash(); }
                fromClick = false;
                return;
            }
            var cp = e.target.closest('.tbx-copy');
            if (cp) { var src = document.getElementById(cp.getAttribute('data-copy')); if (src) copyText(src.textContent, cp); }
        });

        var digits = '', digitTimer = 0;
        document.addEventListener('keydown', function (e) {
            var t = (e.target.tagName || '').toLowerCase();
            if (t === 'input' || t === 'textarea' || t === 'select' || e.target.isContentEditable || e.ctrlKey || e.metaKey || e.altKey) return;
            if (e.target.closest && e.target.closest('.tbx-panel')) return;
            if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
                e.preventDefault();
                pick((cur + (e.key === 'ArrowDown' ? 1 : TOOLS.length - 1)) % TOOLS.length, { hash: true, focus: true });
            } else if (/^[0-9]$/.test(e.key)) {
                clearTimeout(digitTimer);
                digits = (digits + e.key).slice(-2);
                var n = parseInt(digits, 10);
                if (n < 1 || n > TOOLS.length) { digits = e.key; n = parseInt(digits, 10); }
                if (n >= 1 && n <= TOOLS.length) pick(n - 1, { hash: true, open: true, focus: true });
                digitTimer = setTimeout(function () { digits = ''; }, 700);
            }
        });
    }
    return { init: init, cronParse: cronParse, cronDescribe: cronDescribe };
})();

function setFooterYear() {
    var el = $('#footer-year'), y = new Date().getFullYear();
    if (el && y > 2024) el.textContent = '2024-' + y;
}

// Code-block headers and table wrappers change layout, so build them right away (this script sits at the end
// of <body>) instead of after window load. Highlighting waits for DOMContentLoaded, after deferred highlight.js.
enhanceCodeBlocks(); wrapTables();
document.addEventListener('DOMContentLoaded', function () {
    highlightCode();
    initTheme(); renderSocial(); collectGroups(); buildNav(); initDrawer();
    polishRows(); Grep.init(); fillSide(); Toolbox.init();
    buildToc(); postMeta(); buildShare(); buildRelated(); initComments();
    initScroll(); setFooterYear();
});
